# Domain 8. Ethical, Legal, and Professional Issues (16%), KN61-KN71. Pool 32, 8 per test.
# Standards cited from the APA Ethical Principles of Psychologists and Code of Conduct
# (2002, amended 2010 and 2016, effective January 1, 2017).
CAT = "epppEthics"; SEG = "ETH"
